  transform(input) { throw new Error('Not implemented'); }
}
class PassThrough extends FieldMapper { transform(i) { return i; } }
class RenameFields extends FieldMapper { constructor(cfg){ super(); this.map = cfg; } transform(i){ const out={}; for(const k in i){ out[this.map[k]||k]=i[k]; } return out; } }
