class Validator {
  validate(value) { throw new Error('not implemented') }
}

const registry = new Map<string, () => Validator>()

function register(field, factory) { registry.set(field, factory) }

function validate(field, value) {
  const factory = registry.get(field)
  if (!factory) throw new Error('no validator')
  return factory().validate(value)
